{"cards": [{"node_code": "N_f33cb1e6afd9d5b2", "definition": "研究汽车仪表板总成、各类指示仪表、报警装置及信息显示系统的结构形式、工作原理、安装布局及人机交互设计。", "boundary": "本节点聚焦于驾驶员监控车辆状态及获取信息的物理装置与界面。边界在于区分“仪表结构”与“车载娱乐/通信系统”（后者侧重多媒体与网络，若树中有独立节点则归入，否则视语境归入电气或本节点）、“仪表结构”与“传感器原理”（传感器作为独立部件若涉及底层物理原理，需视具体语境，但作为仪表组成部分归本节点）。", "includes": ["车速表、转速表、油量表等指示仪表的结构与原理", "仪表板（Dashboard）的整体结构设计、材料选择及装配", "故障指示灯、报警蜂鸣器及数字显示屏的结构集成"], "excludes": ["车载导航、音响、电话等娱乐通信系统的功能应用", "发动机或底盘内部传感器的独立研发与制造（若未集成于仪表）"], "sibling_distinctions": [{"other_code": "N_477f2c43aa8621ca", "rule": "电气设备及附件侧重电源、照明、信号等基础电气系统；仪表侧重信息读取与显示的人机界面装置。"}, {"other_code": "N_b59740d976fe34eb", "rule": "驾驶室及车身侧重承载结构、外壳及内饰空间；仪表是安装在驾驶室内部的功能性组件。"}], "cross_boundary_rule": "若内容涉及“仪表板与车身内饰的一体化设计”，主挂载驾驶室及车身；若涉及“仪表显示逻辑与传感器信号处理”，主挂载仪表。"}, {"node_code": "N_b59740d976fe34eb", "definition": "研究汽车驾驶室、车身（包括承载式与非承载式）的结构形式、强度刚度设计、空气动力学外形、内饰布局及制造工艺。", "boundary": "本节点聚焦于汽车的外部造型与内部承载空间结构。边界在于区分“车身结构”与“底盘结构”（底盘侧重行驶与传动，车身侧重承载与防护）、“车身设计”与“内饰件”（如座椅、门板等独立内饰件若未涉及整体结构，可归入附属装置或本节点，需视具体深度）。", "includes": ["车身骨架、覆盖件的结构设计与碰撞安全分析", "驾驶室空间布局、人机工程学及内饰整体结构", "车身空气动力学外形设计、涂装及轻量化结构"], "excludes": ["发动机舱内部动力总成结构", "底盘悬挂、转向等行驶系统结构"], "sibling_distinctions": [{"other_code": "N_86e4e87642e6280c", "rule": "汽车底盘（总论）侧重行驶与传动系统的整体架构；驾驶室及车身侧重承载乘客/货物及外部防护结构。"}, {"other_code": "N_f33cb1e6afd9d5b2", "rule": "驾驶室及车身提供安装仪表的空间与结构基础；仪表是安装在其中的具体功能部件。"}], "cross_boundary_rule": "若内容涉及“车身与底盘的连接结构（如副车架安装点）”，主挂载驾驶室及车身；若涉及“底盘整体布局”，主挂载汽车底盘（总论）。"}, {"node_code": "N_8edb18248796fe34eb", "definition": "研究除底盘、发动机、车身及仪表外，汽车上其他辅助性、功能性装置的结构与原理，如空调、座椅、后视镜、雨刮器等。", "boundary": "本节点为“其他”类，收录不属于主要总成（底盘、发动机、车身、仪表、电气）的独立功能部件。边界在于区分“附属装置”与“主要总成”（如空调压缩机若涉及发动机驱动结构，需视语境，但空调系统整体归本节点）、“附属装置”与“车载电子”（如独立的车载电脑归电气或仪表，机械式雨刮归本节点）。", "includes": ["汽车空调、暖风及通风系统的结构与原理", "座椅、安全带、后视镜、雨刮器、遮阳板等内外饰功能件", "行李箱、备胎架、千斤顶等随车工具及储物装置"], "excludes": ["发动机、底盘、车身、仪表、电气系统的核心结构", "车载娱乐、通信及导航系统的电子功能"], "sibling_distinctions": [{"other_code": "N_b59740d976fe34eb", "rule": "驾驶室及车身侧重整体结构与空间；附属装置侧重安装在其中的独立功能组件（如座椅、空调）。"}, {"other_code": "N_477f2c43aa8621ca", "rule": "电气设备及附件侧重电源、照明、信号等电气系统；附属装置侧重机械或机电一体化的辅助功能件（如电动座椅的机械结构）。"}], "cross_boundary_rule": "若内容涉及“电动座椅的电机控制”，主挂载电气设备及附件；若涉及“座椅骨架与调节机构”，主挂载汽车附属装置。"}]}
